package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.apache.commons.compress.utils.ChecksumCalculatingInputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ChecksumCalculatingInputStream_read_TriageGen1Test {

    @Test
    public void testReadReturnsDataAndUpdatesChecksum() throws IOException {
        byte[] data = new byte[]{10, 20, 30};
        Checksum checksum = new CRC32();
        CRC32 expectedChecksum = new CRC32();
        expectedChecksum.update(10);
        expectedChecksum.update(20);
        expectedChecksum.update(30);

        try (InputStream in = new ByteArrayInputStream(data);
             ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(checksum, in)) {

            Assert.assertEquals(10, cis.read());
            Assert.assertEquals(20, cis.read());
            Assert.assertEquals(30, cis.read());
            Assert.assertEquals(-1, cis.read());

            Assert.assertEquals(expectedChecksum.getValue(), cis.getValue());
        }
    }






}

